import type { Lang } from './i18n'

/**
 * A block of article body. Articles used to be a flat `string[]` of paragraphs,
 * which meant an editor could not set a sub-heading or pull out a quote — both
 * were silently flattened on the way in. Blocks fix that.
 *
 * `text` may carry inline markup: `**bold**`, `*italic*` and
 * `[label](https://…)`. It is parsed into React elements by `renderInline()` in
 * ./articleContent — never injected as HTML.
 */
export type Block =
  | { kind: 'p'; text: string }
  | { kind: 'h2'; text: string }
  | { kind: 'quote'; text: string; attribution?: string }
  | { kind: 'image'; src: string; alt: string; credit?: string }

export interface Source {
  label: string
  url: string
}

/**
 * One translated version of an article. English stays in the article's own
 * fields; the other five languages live in `Article.translations`, keyed by
 * language. This is the contract with the Press Tool (docs/TODO.md, item 1):
 * the slug is English and shared, everything language-neutral (`category`,
 * `date`, `image`, `imageCredit`, `author`, `sources`, image `credit`s in
 * blocks) is stored once on the article.
 */
export interface ArticleTranslation {
  title: string
  excerpt: string
  /** Short title for the browser tab and search results. See `Article.seoTitle`. */
  seoTitle?: string
  imageAlt: string
  /** Same block kinds, same inline syntax as the English `content`. */
  content: Block[]
  /** Omitted = the English value. */
  readTime?: string
}

export interface Article {
  slug: string
  category: string
  title: string
  /**
   * Optional short title for the `<title>` tag and the search result.
   *
   * A headline is written for a reader who is already on the page; a search
   * result has about sixty characters before Google cuts it off mid-word.
   * Twelve of the articles here run 72-86 characters, so the end of the
   * sentence is simply lost to anyone finding us through search.
   *
   * Keep it to **55 characters or fewer** — the site appends " | Racespot.tv"
   * and that has to fit too. Front-load the distinctive part: the series, the
   * event, the manufacturer. It must say the same thing the headline says; a
   * search result that promises something the article does not deliver is
   * worse than a truncated one.
   *
   * Omit it and the headline is used, which is right whenever the headline is
   * already short enough.
   */
  seoTitle?: string
  excerpt: string
  /**
   * Publication day, YYYY-MM-DD — **the sort key**. Since 2026-09-17 this is
   * the day the piece went out on racespot.tv, or an earlier day the desk chose
   * so that an older story files where it belongs. Never the day the story
   * broke. Lists sort by it through sortedArticles(), never by array position:
   * the Press Tool keeps inserting at the top regardless of date.
   */
  date: string
  /** First publication, ISO 8601 UTC. Tie-breaker within a day; sitemap lastmod when nothing was updated. */
  publishedAt: string
  /** Only when the entry was published again — a correction, new material, translations. Keeps its `date`, so it does not move. */
  updatedAt?: string
  readTime: string
  image: string
  imageAlt: string
  /** Who to credit for the hero image. Shown under it when present. */
  imageCredit?: string
  /** Byline. Articles written before bylines existed simply have none. */
  author?: string
  /**
   * Where the story came from. Deliberately NOT rendered in the article body —
   * it is an editorial record, kept with the article so it stays available for
   * structured data and for anyone checking the origin later.
   */
  sources?: Source[]
  /** Editorial beats, finer than `category`; several share one category. Carried for a topic filter or press menu, not rendered yet. */
  topics?: { id: string; label: string }[]
  /** Free tags from the Press Tool. Carried, not rendered. */
  tags?: string[]
  /**
   * `string[]` is still valid and means "these are plain paragraphs", so every
   * article written before blocks existed keeps working untouched. Read it
   * through `toBlocks()` from ./articleContent rather than directly.
   */
  content: string[] | Block[]
  /**
   * The other five languages. A missing language renders the English text
   * and gets no `hreflang` — a half-translated page is never indexed.
   */
  translations?: Partial<Record<Exclude<Lang, 'en'>, ArticleTranslation>>
}

/**
 * Every list of articles goes through this: newest publication day first, and
 * within a day the later first publication first. The array's own order means
 * nothing — the Press Tool inserts at the top whatever the date, and the desk
 * publishes older pieces with the day they belong to.
 */
export function sortedArticles(): Article[] {
  return [...ARTICLES].sort((a, b) => {
    if (a.date !== b.date) return a.date < b.date ? 1 : -1
    return a.publishedAt < b.publishedAt ? 1 : a.publishedAt > b.publishedAt ? -1 : 0
  })
}

